import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen2Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Enable pretty printing to make verification easier if needed, 
        // though we mostly rely on the internal state via asParser()
        mapper.enable(SerializationFeature.INDENT_OUTPUT);
        tokenBuffer = new TokenBuffer(mapper);
    }

    /**
     * Tests that writeEndArray correctly appends the END_ARRAY token 
     * and correctly manages the JsonWriteContext hierarchy.
     */
    @Test
    public void testWriteEndArray_Success() throws IOException, JsonGenerationException {
        // 1. Test basic functionality: Start Array -> Write Value -> End Array
        tokenBuffer.writeStartArray();
        tokenBuffer.writeNumber(1);
        tokenBuffer.writeEndArray();

        // Verify the sequence of tokens using a parser
        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }

    /**
     * Tests the context nesting logic. 
     * When writeEndArray is called, the current context should move to the parent.
     */
    @Test
    public void testWriteEndArray_ContextNesting() throws IOException, JsonGenerationException {
        // Start an Object
        tokenBuffer.writeStartObject();
        // Start an Array inside the Object
        tokenBuffer.writeFieldName("list");
        tokenBuffer.writeStartArray();

        // Before ending array, the context is inside the array
        // We verify context behavior by checking the structure
        tokenBuffer.writeEndArray();

        // End the object
        tokenBuffer.writeEndObject();

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("list", parser.getCurrentName());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    /**
     * Tests the "unbalanced" logic mentioned in the code comments:
     * If getParent() is null, it should not throw an exception and just stay at the current context.
     */
    @Test
    public void testWriteEndArray_NoParentContext() throws IOException, JsonGenerationException {
        // Create a buffer and immediately call writeEndArray without starting any structure.
        // This simulates a state where _writeContext has no parent (root level).
        tokenBuffer.writeEndArray();

        JsonParser parser = tokenBuffer.asParser();
        // Because we appended END_ARRAY to a root context, the first token is END_ARRAY
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }

    /**
     * Tests deep nesting to ensure the context pointer moves up multiple levels correctly.
     */
    @Test
    public void testWriteEndArray_DeepNesting() throws IOException, JsonGenerationException {
        tokenBuffer.writeStartArray(); // Level 1
        tokenBuffer.writeStartArray(); // Level 2
        tokenBuffer.writeStartArray(); // Level 3

        tokenBuffer.writeEndArray(); // Close Level 3
        tokenBuffer.writeEndArray(); // Close Level 2
        tokenBuffer.writeEndArray(); // Close Level 1

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }
}
